// Original, bounded educational synthesis. No recordings or Strudel runtime.
let context=null,nodes=[],timer=null,token=0;
export function stop(){token++;clearTimeout(timer);nodes.forEach(n=>{try{n.stop()}catch{}try{n.disconnect()}catch{}});nodes=[];if(context){context.close().catch(()=>{});context=null}document.querySelectorAll('.audio-status').forEach(e=>e.textContent='Stopped.');}
export async function play({notes=[60,64,67],beats=null,bpm=100,chord=false,wave='sine',beatsPerBar=4,barCount=1,chords=null},status){stop();const run=token;try{context=new (window.AudioContext||window.webkitAudioContext)();await context.resume();if(run!==token)return;const c=context;const master=c.createGain();master.gain.value=.055;master.connect(c.destination);const duration=beats?Math.min(12,beatsPerBar*barCount*60/bpm):Math.min(12,chords?chords.length*.9+.2:chord?2.5:notes.length*.55+.2);const tone=(m,t,len)=>{const o=c.createOscillator(),g=c.createGain();o.type=wave;o.frequency.value=440*2**((m-69)/12);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.7/Math.max(1,chords?Math.max(...chords.map(x=>x.length)):chord?notes.length:1),t+.015);g.gain.exponentialRampToValueAtTime(.001,t+len);o.connect(g);g.connect(master);o.start(t);o.stop(t+len+.03);nodes.push(o)};if(chords)chords.slice(0,8).forEach((ns,i)=>ns.forEach(m=>tone(m,c.currentTime+.05+i*.9,.8)));else if(beats)beats.slice(0,64).forEach(b=>tone(76,c.currentTime+.05+b*60/bpm,.08));else notes.slice(0,20).forEach((m,i)=>tone(m,c.currentTime+.05+(chord?0:i*.55),chord?2.2:.45));status.textContent='Playing a quiet, original synthesized example…';timer=setTimeout(()=>{stop();status.textContent='Example finished. Replay whenever you like.'},(duration+.15)*1000)}catch{if(run!==token)return;stop();status.textContent='Audio unavailable in this browser. The labeled visual shows the same example.'}}
window.addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
